  --text-secondary: #787774;
  --border-color: #EAEAEA;
  --accent: #3B82F6;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg-primary: #1A1A1A;
    --bg-card: #242424;
