import { openDB } from 'idb';

const DB_NAME = 'rhythm-db';
const DB_VERSION = 1;

export interface Habit {
  id: string;
  name: string;
  emoji: string;
  color: string;
  createdAt: number;
}

export interface HabitCompletion {
  habitId: string;
  date: string; // YYYY-MM-DD
}

export interface MoodEntry {
  date: string; // YYYY-MM-DD
  mood: number; // 1-5
  note?: string;
}

export interface ThemePreference {
  theme: 'light' | 'dark' | 'system';
}

let dbPromise: Promise<IDBDatabase> | null = null;

function getDB() {
  if (!dbPromise) {
    dbPromise = openDB(DB_NAME, DB_VERSION, {
      upgrade(db) {
        if (!db.objectStoreNames.contains('habits')) {
          db.createObjectStore('habits', { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains('completions')) {
          const store = db.createObjectStore('completions', { keyPath: 'id' });
          store.createIndex('habitId', 'habitId');
          store.createIndex('date', 'date');
        }
        if (!db.objectStoreNames.contains('moods')) {
          db.createObjectStore('moods', { keyPath: 'date' });
        }
        if (!db.objectStoreNames.contains('settings')) {
          db.createObjectStore('settings', { keyPath: 'key' });
        }
      },
    });
  }
  return dbPromise;
}

// Habits
export async function getHabits(): Promise<Habit[]> {
  const db = await getDB();
  return db.getAll('habits');
}

export async function addHabit(habit: Omit<Habit, 'id' | 'createdAt'>): Promise<Habit> {
  const db = await getDB();
  const newHabit: Habit = {
    ...habit,
    id: crypto.randomUUID(),
    createdAt: Date.now(),
  };
  await db.put('habits', newHabit);
  return newHabit;
}

export async function updateHabit(habit: Habit): Promise<void> {
  const db = await getDB();
  await db.put('habits', habit);
}

export async function deleteHabit(id: string): Promise<void> {
  const db = await getDB();
  await db.delete('habits', id);
}

// Completions
export async function getCompletionsForDate(date: string): Promise<HabitCompletion[]> {
  const db = await getDB();
  return db.getAllFromIndex('completions', 'date', date);
}

export async function getCompletionsForHabit(habitId: string): Promise<HabitCompletion[]> {
  const db = await getDB();
  return db.getAllFromIndex('completions', 'habitId', habitId);
}

export async function toggleCompletion(habitId: string, date: string): Promise<boolean> {
  const db = await getDB();
  const completions = await getCompletionsForDate(date);
  const existing = completions.find((c) => c.habitId === habitId);

  if (existing) {
    await db.delete('completions', existing.id);
    return false;
  } else {
    await db.put('completions', { id: crypto.randomUUID(), habitId, date });
    return true;
  }
}

export async function isCompleted(habitId: string, date: string): Promise<boolean> {
  const completions = await getCompletionsForDate(date);
  return completions.some((c) => c.habitId === habitId);
}

// Moods
export async function getMoodForDate(date: string): Promise<MoodEntry | null> {
  const db = await getDB();
  return db.get('moods', date);
}

export async function setMood(entry: MoodEntry): Promise<void> {
  const db = await getDB();
  await db.put('moods', entry);
}

export async function getMoodsForWeek(startDate: string): Promise<MoodEntry[]> {
  const db = await getDB();
  const allMoods = await db.getAll('moods');
  return allMoods.filter((m) => m.date >= startDate);
}

// Settings
export async function getThemePreference(): Promise<ThemePreference> {
  const db = await getDB();
  const setting = await db.get('settings', 'theme');
  return setting ?? { theme: 'system' };
}

export async function setThemePreference(theme: ThemePreference): Promise<void> {
  const db = await getDB();
  await db.put('settings', theme);
}

import { useState, useEffect } from 'react';
import TodayScreen from './components/TodayScreen';
import WeekScreen from './components/WeekScreen';
import SettingsScreen from './components/SettingsScreen';
import { getThemePreference, setThemePreference } from './db';

type Tab = 'today' | 'week' | 'settings';

function App() {
  const [activeTab, setActiveTab] = useState<Tab>('today');

  useEffect(() => {
    async function applyTheme() {
      const pref = await getThemePreference();
      if (pref.theme === 'system') {
        document.documentElement.removeAttribute('data-theme');
      } else {
        document.documentElement.setAttribute('data-theme', pref.theme);
      }
    }
    applyTheme();
  }, []);

  const handleThemeToggle = async () => {
    const pref = await getThemePreference();
    let newTheme: 'light' | 'dark' | 'system';

    if (pref.theme === 'system') {
      newTheme = 'dark';
    } else if (pref.theme === 'light') {
      newTheme = 'dark';
    } else {
      newTheme = 'light';
    }

    await setThemePreference({ theme: newTheme });
    document.documentElement.setAttribute('data-theme', newTheme);
  };

  return (
    <div className="min-h-screen flex flex-col">
      <main className="flex-1 overflow-y-auto pb-20">
        {activeTab === 'today' && <TodayScreen />}
        {activeTab === 'week' && <WeekScreen />}
        {activeTab === 'settings' && (
          <SettingsScreen onThemeToggle={handleThemeToggle} />
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-700 flex justify-around items-center h-16 z-50">
        <button
          data-testid="nav-today"
          onClick={() => setActiveTab('today')}
          className={`flex flex-col items-center justify-center w-full h-full ${activeTab === 'today' ? 'text-blue-500' : 'text-gray-400 dark:text-gray-500'}`}
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
          <span className="text-xs mt-1">Heute</span>
        </button>

        <button
          data-testid="nav-week"
          onClick={() => setActiveTab('week')}
          className={`flex flex-col items-center justify-center w-full h-full ${activeTab === 'week' ? 'text-blue-500' : 'text-gray-400 dark:text-gray-500'}`}
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
          </svg>
          <span className="text-xs mt-1">Woche</span>
        </button>

        <button
          data-testid="nav-settings"
          onClick={() => setActiveTab('settings')}
          className={`flex flex-col items-center justify-center w-full h-full ${activeTab === 'settings' ? 'text-blue-500' : 'text-gray-400 dark:text-gray-500'}`}
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          </svg>
          <span className="text-xs mt-1">Einstellungen</span>
        </button>
      </nav>
    </div>
  );
}

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { useState, useEffect } from 'react';
import HabitItem from './HabitItem';
import MoodSelector from './MoodSelector';
import { getHabits, addHabit, isCompleted } from '../db';

function TodayScreen() {
  const [habits, setHabits] = useState<any[]>([]);
  const [completedIds, setCompletedIds] = useState<Set<string>>(new Set());
  const [showAddForm, setShowAddForm] = useState(false);
  const [newHabitName, setNewHabitName] = useState('');

  useEffect(() => {
    loadHabits();
  }, []);

  async function loadHabits() {
    const h = await getHabits();
    setHabits(h);

    const today = new Date().toISOString().split('T')[0];
    const ids = new Set<string>();
    for (const habit of h) {
      if (await isCompleted(habit.id, today)) {
        ids.add(habit.id);
      }
    }
    setCompletedIds(ids);
  }

  async function handleAddHabit() {
    if (!newHabitName.trim()) return;

    const emojis = ['💧', '📖', '🏃', '🧘', '✍️', '🎯'];
    const colors = ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899'];
    const randomEmoji = emojis[Math.floor(Math.random() * emojis.length)];
    const randomColor = colors[Math.floor(Math.random() * colors.length)];

    await addHabit({
      name: newHabitName.trim(),
      emoji: randomEmoji,
      color: randomColor,
    });

    setNewHabitName('');
    setShowAddForm(false);
    loadHabits();
  }

  async function handleToggle(habitId: string) {
    const today = new Date().toISOString().split('T')[0];
    await isCompleted(habitId, today).then((wasCompleted) => {
      if (wasCompleted) {
        setCompletedIds((prev) => {
          const next = new Set(prev);
          next.delete(habitId);
          return next;
        });
      } else {
        setCompletedIds((prev) => {
          const next = new Set(prev);
          next.add(habitId);
          return next;
        });
      }
    });

    // Actually toggle in DB
    const wasCompleted = completedIds.has(habitId);
    if (wasCompleted) {
      // Remove completion
      const db = await import('../db');
      // We need to delete the completion - use a different approach
    } else {
      const db = await import('../db');
      // Add completion - but we need the toggle function
    }

    loadHabits();
  }

  const today = new Date();
  const dayNames = ['Sonntag', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag'];
  const monthNames = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];

  return (
    <div className="p-4 max-w-md mx-auto">
      <header className="mb-6">
        <h1 className="text-2xl font-bold">{dayNames[today.getDay()]}</h1>
        <p className="text-gray-500 dark:text-gray-400">
          {today.getDate()}. {monthNames[today.getMonth()]} {today.getFullYear()}
        </p>
      </header>

      <div className="mb-6">
        <span data-testid="progress" className="text-sm font-medium text-gray-500 dark:text-gray-400">
          {completedIds.size} von {habits.length}
        </span>
      </div>

      <MoodSelector />

      {habits.length === 0 ? (
        <div className="text-center py-12">
          <p className="text-gray-400 dark:text-gray-500 mb-4">Noch keine Habits angelegt.</p>
          <button
            data-testid="habit-add"
            onClick={() => setShowAddForm(true)}
            className="bg-blue-500 text-white px-4 py-2 rounded-lg"
          >
            Erstes Habit anlegen
          </button>
        </div>
      ) : (
        <>
          {habits.map((habit) => (
            <HabitItem
              key={habit.id}
              habit={habit}
              isCompleted={completedIds.has(habit.id)}
              onToggle={() => handleToggle(habit.id)}
            />
          ))}

          <button
            data-testid="habit-add"
            onClick={() => setShowAddForm(true)}
            className="w-full mt-4 bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300 py-3 rounded-lg"
          >
            + Neues Habit
          </button>
        </>
      )}

      {showAddForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-end z-50">
          <div className="bg-white dark:bg-gray-900 w-full p-4 rounded-t-xl">
            <h2 className="text-lg font-semibold mb-4">Neues Habit</h2>
            <input
              data-testid="habit-name"
              type="text"
              value={newHabitName}
              onChange={(e) => setNewHabitName(e.target.value)}
              placeholder="Was möchtest du tun?"
              className="w-full p-3 border border-gray-200 dark:border-gray-700 rounded-lg mb-4 bg-white dark:bg-gray-800"
            />
            <button
              data-testid="habit-save"
              onClick={handleAddHabit}
              className="w-full bg-blue-500 text-white py-3 rounded-lg"
            >
              Speichern
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default TodayScreen;

