import { useState, useEffect } from 'react';
import { getCompletionsForHabit } from '../db';

interface HabitItemProps {
  habit: any;
  isCompleted: boolean;
  onToggle: () => void;
}

function HabitItem({ habit, isCompleted, onToggle }: HabitItemProps) {
  const [currentStreak, setCurrentStreak] = useState(0);
  const [longestStreak, setLongestStreak] = useState(0);

  useEffect(() => {
    calculateStreaks();
  }, [isCompleted]);

  async function calculateStreaks() {
    const completions = await getCompletionsForHabit(habit.id);
    const dates = completions.map((c) => c.date).sort();

    // Calculate current streak
    let streak = 0;
    const today = new Date();
    for (let i = 0; i < dates.length; i++) {
      const date = new Date(dates[i]);
      const diffDays = Math.floor((today.getTime() - date.getTime()) / (1000 * 60 * 60 * 24));
      if (diffDays === i) {
        streak++;
      } else {
        break;
      }
    }
    setCurrentStreak(streak);

    // Calculate longest streak
    let maxStreak = 0;
    let currentRun = 0;
    for (let i = 0; i < dates.length; i++) {
      if (i === 0) {
        currentRun = 1;
      } else {
        const prevDate = new Date(dates[i - 1]);
        const currDate = new Date(dates[i]);
        const diff = Math.floor((currDate.getTime() - prevDate.getTime()) / (1000 * 60 * 60 * 24));
        if (diff === 1) {
          currentRun++;
        } else {
          maxStreak = Math.max(maxStreak, currentRun);
          currentRun = 1;
        }
      }
    }
    maxStreak = Math.max(maxStreak, currentRun);
    setLongestStreak(maxStreak);
  }

  return (
    <div data-testid="habit-item" className="flex items-center justify-between p-4 bg-white dark:bg-gray-800 rounded-xl mb-3 border border-gray-100 dark:border-gray-700">
      <div className="flex items-center gap-3">
        <span className="text-2xl">{habit.emoji}</span>
        <div>
          <h3 className="font-medium">{habit.name}</h3>
          <span data-testid="habit-streak" className="text-xs text-gray-400 dark:text-gray-500">
            {currentStreak} / {longestStreak} Tage
          </span>
        </div>
      </div>

      <button
        data-testid="habit-toggle"
        aria-pressed={isCompleted}
        onClick={onToggle}
        className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${
          isCompleted
            ? 'bg-green-500 text-white'
            : 'border-2 border-gray-300 dark:border-gray-600 text-transparent'
        }`}
      >
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
        </svg>
      </button>
    </div>
  );
}

export default HabitItem;

import { useState, useEffect } from 'react';
import { getMoodForDate, setMood } from '../db';

const MOODS = [
  { value: 1, emoji: '😞', label: 'Schlecht' },
  { value: 2, emoji: '😕', label: 'So so' },
  { value: 3, emoji: '😐', label: 'Okay' },
  { value: 4, emoji: '😊', label: 'Gut' },
  { value: 5, emoji: '😄', label: 'Super' },
];

function MoodSelector() {
  const [selectedMood, setSelectedMood] = useState<number | null>(null);

  useEffect(() => {
    loadTodayMood();
  }, []);

  async function loadTodayMood() {
    const today = new Date().toISOString().split('T')[0];
    const mood = await getMoodForDate(today);
    if (mood) {
      setSelectedMood(mood.mood);
    }
  }

  async function handleSelectMood(value: number) {
    setSelectedMood(value);
    const today = new Date().toISOString().split('T')[0];
    await setMood({ date: today, mood: value });
  }

  return (
    <div className="mb-6 p-4 bg-white dark:bg-gray-800 rounded-xl border border-gray-100 dark:border-gray-700">
      <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-3">Wie fühlst du dich heute?</h3>
      <div className="flex justify-between">
        {MOODS.map((mood) => (
          <button
            key={mood.value}
            data-testid={`mood-${mood.value}`}
            aria-pressed={selectedMood === mood.value}
            onClick={() => handleSelectMood(mood.value)}
            className={`w-12 h-12 rounded-full flex items-center justify-center text-xl transition-all ${
              selectedMood === mood.value
                ? 'bg-blue-500 text-white scale-110'
                : 'text-gray-400 dark:text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'
            }`}
          >
            {mood.emoji}
          </button>
        ))}
      </div>
    </div>
  );
}

export default MoodSelector;

import { useState, useEffect } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { getHabits, getCompletionsForDate, getMoodsForWeek } from '../db';

function WeekScreen() {
  const [chartData, setChartData] = useState<any[]>([]);

  useEffect(() => {
    loadWeekData();
  }, []);

  async function loadWeekData() {
    const habits = await getHabits();
    const today = new Date();
    const data: any[] = [];

    for (let i = 6; i >= 0; i--) {
      const date = new Date(today);
      date.setDate(date.getDate() - i);
      const dateStr = date.toISOString().split('T')[0];

      let completedCount = 0;
      for (const habit of habits) {
        const completions = await getCompletionsForDate(dateStr);
        if (completions.some((c) => c.habitId === habit.id)) {
          completedCount++;
        }
      }

      const dayNames = ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa'];
      data.push({
        date: dayNames[date.getDay()],
        completions: completedCount,
      });
    }

    setChartData(data);
  }

  return (
    <div className="p-4 max-w-md mx-auto">
      <h1 className="text-2xl font-bold mb-6">Woche</h1>

      <div data-testid="week-chart" className="bg-white dark:bg-gray-800 rounded-xl p-4 border border-gray-100 dark:border-gray-700">
        <ResponsiveContainer width="100%" height={250}>
          <BarChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} />
            <XAxis dataKey="date" tick={{ fill: '#787774' }} />
            <YAxis hide domain={[0, 5]} />
            <Tooltip />
            <Bar dataKey="completions" fill="#3B82F6" radius={[4, 4, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>

      <p className="text-sm text-gray-400 dark:text-gray-500 mt-4">
        Erledigte Habits pro Tag in den letzten 7 Tagen.
      </p>
    </div>
  );
}

export default WeekScreen;

interface SettingsScreenProps {
  onThemeToggle: () => void;
}

function SettingsScreen({ onThemeToggle }: SettingsScreenProps) {
  return (
    <div className="p-4 max-w-md mx-auto">
      <h1 className="text-2xl font-bold mb-6">Einstellungen</h1>

      <div className="bg-white dark:bg-gray-800 rounded-xl p-4 border border-gray-100 dark:border-gray-700">
        <div className="flex items-center justify-between">
          <span>Dunkler Modus</span>
          <button
            data-testid="theme-toggle"
            onClick={onThemeToggle}
            className="w-12 h-6 bg-gray-300 dark:bg-blue-500 rounded-full relative transition-colors"
          >
            <span className="absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform dark:translate-x-6"></span>
          </button>
        </div>
      </div>

      <p className="text-sm text-gray-400 dark:text-gray-500 mt-6">
        Rhythm v1.0 - Habit- und Stimmungs-Tracker
      </p>
    </div>
  );
}

export default SettingsScreen;

import sharp from 'sharp';

async function generateIcon(size, filename) {
  // Create a simple icon with a circle and checkmark
  const svg = `
    <svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" xmlns="http://www.w3.org/2000/svg">
      <rect width="${size}" height="${size}" rx="32" fill="#F7F6F3"/>
      <circle cx="${size/2}" cy="${size/2}" r="${size*0.35}" fill="#3B82F6"/>
      <path d="M${size*0.35} ${size/2} L${size*0.48} ${size*0.63} L${size*0.65} ${size*0.4}" stroke="white" stroke-width="${size*0.08}" fill="none" stroke-linecap="round" stroke-linejoin="round"/>
    </svg>
  `;

  await sharp(Buffer.from(svg))
    .resize(size, size)
    .png()
    .toFile(`public/${filename}`);

  console.log(`Generated ${filename} (${size}x${size})`);
}

async function main() {
  await generateIcon(192, 'icon-192.png');
  await generateIcon(512, 'icon-512.png');
}

main().catch(console.error);

import { openDB, IDBPDatabase } from 'idb';

const DB_NAME = 'rhythm-db';
const DB_VERSION = 1;

export interface Habit {
  id: string;
  name: string;
  emoji: string;
  color: string;
  createdAt: number;
}

export interface HabitCompletion {
  id: string;
  habitId: string;
  date: string; // YYYY-MM-DD
}

export interface MoodEntry {
  date: string; // YYYY-MM-DD
  mood: number; // 1-5
  note?: string;
}

export interface ThemePreference {
  key: string;
  theme: 'light' | 'dark' | 'system';
}

let dbPromise: Promise<IDBPDatabase> | null = null;

function getDB() {
  if (!dbPromise) {
    dbPromise = openDB(DB_NAME, DB_VERSION, {
      upgrade(db) {
        if (!db.objectStoreNames.contains('habits')) {
          db.createObjectStore('habits', { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains('completions')) {
          const store = db.createObjectStore('completions', { keyPath: 'id' });
          store.createIndex('habitId', 'habitId');
          store.createIndex('date', 'date');
        }
        if (!db.objectStoreNames.contains('moods')) {
          db.createObjectStore('moods', { keyPath: 'date' });
        }
        if (!db.objectStoreNames.contains('settings')) {
          db.createObjectStore('settings', { keyPath: 'key' });
        }
      },
    });
  }
  return dbPromise;
}

// Habits
export async function getHabits(): Promise<Habit[]> {
  const db = await getDB();
  return db.getAll('habits');
}

export async function addHabit(habit: Omit<Habit, 'id' | 'createdAt'>): Promise<Habit> {
  const db = await getDB();
  const newHabit: Habit = {
    ...habit,
    id: crypto.randomUUID(),
    createdAt: Date.now(),
  };
  await db.put('habits', newHabit);
  return newHabit;
}

export async function updateHabit(habit: Habit): Promise<void> {
  const db = await getDB();
  await db.put('habits', habit);
}

export async function deleteHabit(id: string): Promise<void> {
  const db = await getDB();
  await db.delete('habits', id);
}

// Completions
export async function getCompletionsForDate(date: string): Promise<HabitCompletion[]> {
  const db = await getDB();
  return db.getAllFromIndex('completions', 'date', date);
}

export async function getCompletionsForHabit(habitId: string): Promise<HabitCompletion[]> {
  const db = await getDB();
  return db.getAllFromIndex('completions', 'habitId', habitId);
}

export async function toggleCompletion(habitId: string, date: string): Promise<boolean> {
  const db = await getDB();
  const completions = await getCompletionsForDate(date);
  const existing = completions.find((c) => c.habitId === habitId);

  if (existing) {
    await db.delete('completions', existing.id);
    return false;
  } else {
    await db.put('completions', { id: crypto.randomUUID(), habitId, date });
    return true;
  }
}

export async function isCompleted(habitId: string, date: string): Promise<boolean> {
  const completions = await getCompletionsForDate(date);
  return completions.some((c) => c.habitId === habitId);
}

// Moods
export async function getMoodForDate(date: string): Promise<MoodEntry | null> {
  const db = await getDB();
  return db.get('moods', date);
}

export async function setMood(entry: MoodEntry): Promise<void> {
  const db = await getDB();
  await db.put('moods', entry);
}

export async function getMoodsForWeek(startDate: string): Promise<MoodEntry[]> {
  const db = await getDB();
  const allMoods = await db.getAll('moods');
  return allMoods.filter((m: MoodEntry) => m.date >= startDate);
}

// Settings
export async function getThemePreference(): Promise<ThemePreference> {
  const db = await getDB();
  const setting = await db.get('settings', 'theme');
  return setting ?? { key: 'theme', theme: 'system' };
}

export async function setThemePreference(theme: ThemePreference): Promise<void> {
  const db = await getDB();
  await db.put('settings', theme);
}

